window.RI1_UNITS = {"3":{"unit":3,"code":"RI1-U03","title":"THE POWER OF MUSIC","startNumber":50,"endNumber":89,"entries":[{"number":50,"term":"attract (v) >< distract (v)","spoken":"attract , distract","ipa":"attract /əˈtrækt/ · distract /dɪˈstrækt/","type":"verb · word family","meaning":"thu hút sự chú ý >< làm sao nhãng","definition":"To attract is to draw attention or interest; to distract is to take attention away.","note":"Dấu >< chỉ cặp từ trái nghĩa; học cả hai chiều để nhận biết trong văn cảnh.","example":"Bright colours attract visitors, while loud background music may distract them."},{"number":51,"term":"immediate (a) · immediately (adv)","spoken":"immediate , immediately","ipa":"immediate /ˌɪˈmiːˌdiət/ · immediately /ˌɪˈmiːˌdiətli/","type":"adjective · adverb · word family","meaning":"ngay lập tức/tức thời · ngay lập tức","definition":"Happening without delay; immediately is the corresponding adverb.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"The music had an immediate effect, and the patient's breathing slowed immediately."},{"number":52,"term":"pay attention to sb/st ~ take notice of sb/st # at short notice","spoken":"pay attention to somebody or something , take notice of somebody or something , at short notice","ipa":"pay /peɪ/ · attention /əˈtɛnʃən/ · take /teɪk/ · notice /ˈnoʊtəs/ · short /ʃɔːrt/","type":"phrase / pattern · word family","meaning":"chú ý đến ai/điều gì # với rất ít thời gian báo trước","definition":"To pay attention to something; at short notice means with little warning time.","note":"take notice of/pay attention to: chú ý; at short notice: với rất ít thời gian báo trước.","example":"Please take notice of the change, although it was announced at very short notice."},{"number":53,"term":"motivate (v) · motivation (n)","spoken":"motivate , motivation","ipa":"motivate /ˈmoʊtəˌveɪt/ · motivation /ˌmoʊtəˈveɪʃən/","type":"verb · noun · word family","meaning":"tạo động lực · động lực","definition":"To give someone a reason or desire to act; motivation is that reason or desire.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"A clear goal can motivate learners and strengthen their motivation to practise."},{"number":54,"term":"range (n)","spoken":"range","ipa":"range /reɪndʒ/","type":"noun","meaning":"phạm vi","definition":"The full variety, extent, or set of things between two limits.","note":"","example":"The study examined a wide range of musical styles and emotional responses."},{"number":55,"term":"psychology (n) · psychologist (n)","spoken":"psychology , psychologist","ipa":"psychology /saɪˈkɑːlədʒi/ · psychologist /saɪˈkɑːlədʒəst/","type":"noun · word family","meaning":"tâm lí học · nhà/chuyên gia tâm lí học","definition":"The scientific study of the mind and behaviour; a psychologist is a specialist in this field.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"A psychologist used principles from psychology to examine how stress affects memory."},{"number":56,"term":"general (a) · generally (adv) ~ in general >< in particular","spoken":"general , generally , in general , in particular","ipa":"general /ˈdʒɛnɚəl/ · generally /ˈdʒɛnɚəli/ · particular /pɚˈtɪkjəlɚ/","type":"adjective · adverb · phrase / pattern · word family","meaning":"chung/tổng quát · nhìn chung >< nói riêng/đặc biệt là","definition":"Usually or as a whole; specifically or especially.","note":"in general nghĩa là xét tổng thể; in particular nghĩa là riêng một người/vật/điểm cụ thể.","example":"In general, the class enjoys English; Linh, in particular, enjoys reading."},{"number":57,"term":"cognitive (a) · cognition (n)","spoken":"cognitive , cognition","ipa":"cognitive /ˈkɑːɡnɪtɪv/ · cognition /kɑˈɡnɪʃən/","type":"noun · adjective · word family","meaning":"thuộc nhận thức · khả năng/quá trình nhận thức","definition":"Related to mental processes such as thinking, learning, memory, and understanding.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"The study examined the cognitive skills involved in memory and learning."},{"number":58,"term":"combine (v) A with B · combination (n)","spoken":"combine A with B , combination","ipa":"combine /kəmˈbaɪn/ · combination /ˌkɑːmbəˈneɪʃən/","type":"verb · noun · word family","meaning":"kết hợp một thứ với thứ khác · sự/sự vật kết hợp","definition":"To join two things together; things joined together.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Combine rice with vegetables to make a healthy combination."},{"number":59,"term":"depress (v) · depressed (a) · depressing (a) · depression (n)","spoken":"depress , depressed , depressing , depression","ipa":"depress /dɪˈprɛs/ · depressed /dɪˈprɛst/ · depressing /dɪˈprɛsɪŋ/ · depression /dɪˈprɛʃən/","type":"verb · noun · adjective · word family","meaning":"làm buồn/suy sụp · cảm thấy buồn/suy sụp · gây buồn/chán · sự trầm cảm/suy sụp","definition":"To make someone very unhappy; causing sadness; very unhappy; serious sadness.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Long periods of sadness can depress people; a depressing situation may make someone feel depressed and can lead to depression."},{"number":60,"term":"social (a) · society (n)","spoken":"social , society","ipa":"social /ˈsoʊʃəl/ · society /səˈsaɪəti/","type":"noun · adjective · word family","meaning":"thuộc xã hội/giao tiếp · xã hội","definition":"Social relates to society or interaction with other people; society is the community in which people live.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Social contact supports healthy relationships within a society."},{"number":61,"term":"adjust (v) to st","spoken":"adjust to something","ipa":"adjust /əˈdʒʌst/","type":"verb · phrase / pattern","meaning":"điều chỉnh, thích nghi","definition":"To make a small change so that something works better, or to become comfortable in a new situation.","note":"Giữ đúng mẫu từ đi kèm: adjust (v) to st.","example":"The patient adjusted to the new rhythm after several minutes."},{"number":62,"term":"predict (v) · predictable (a) >< unpredictable (a)","spoken":"predict , predictable , unpredictable","ipa":"predict /prɪˈdɪkt/ · predictable /prɪˈdɪktəbəl/ · unpredictable /ˌʌnprɪˈdɪktəbəl/","type":"verb · adjective · word family","meaning":"dự đoán · có thể đoán trước >< không thể đoán trước","definition":"To say what is likely to happen; a statement about the future.","note":"Dấu >< chỉ cặp từ trái nghĩa; học cả hai chiều để nhận biết trong văn cảnh.","example":"Experts predict rain, but the prediction may change because the weather is unpredictable."},{"number":63,"term":"according to sb / st","spoken":"according to somebody or something","ipa":"according /əˈkɔːrdɪŋ/","type":"phrase / pattern","meaning":"theo ai / cái gì","definition":"As stated or reported by a person or source.","note":"according to + người/nguồn; không dùng according to me để nêu ý kiến cá nhân.","example":"According to the study, calm music can reduce stress before a test."},{"number":64,"term":"certain (a) ~ sure (a)","spoken":"certain , sure","ipa":"certain /ˈsɝːtən/ · sure /ʃʊr/","type":"adjective · word family","meaning":"chắc chắn","definition":"Sure about something; the state of being sure.","note":"certain trang trọng hơn; sure tự nhiên hơn trong giao tiếp. Cả hai có thể đi với of/about/that.","example":"I am certain, or sure, that the answer is correct, but complete certainty needs more evidence."},{"number":65,"term":"orchestra (n) # choir (n)","spoken":"orchestra , choir","ipa":"orchestra /ˈɔːrkəstrə/ · choir /ˈkwaɪɚ/","type":"noun · word family","meaning":"dàn nhạc # dàn hợp xướng","definition":"An orchestra is a large group of instrumentalists; a choir is a group of singers.","note":"orchestra là dàn nhạc; choir là dàn hợp xướng gồm người hát.","example":"The orchestra played below the stage while the choir performed behind the actors."},{"number":66,"term":"ignore (v)","spoken":"ignore","ipa":"ignore /ˌɪˈɡnɔːr/","type":"verb","meaning":"phớt lờ, lảng tránh","definition":"To give no attention to someone or something.","note":"ignore thường là cố tình không chú ý; neglect là bỏ bê hoặc không chăm sóc đúng trách nhiệm trong một thời gian.","example":"The brain cannot simply ignore a sudden change in rhythm."},{"number":67,"term":"stroke (n)","spoken":"stroke","ipa":"stroke /stroʊk/","type":"noun","meaning":"bệnh đột quỵ","definition":"A sudden medical condition in which blood flow to part of the brain is interrupted.","note":"","example":"After the stroke, the patient used music to support movement and speech."},{"number":68,"term":"patient (n)","spoken":"patient","ipa":"patient /ˈpeɪʃənt/","type":"noun","meaning":"bệnh nhân","definition":"A person who receives medical care or treatment.","note":"","example":"Each patient received the same treatment during the study."},{"number":69,"term":"ordinary (a) · ordinary people","spoken":"ordinary , ordinary people","ipa":"ordinary /ˈɔːrdəˌnɛri/ · people /ˈpiːpəl/","type":"adjective · word family","meaning":"bình thường/thông thường · người dân thường","definition":"Normal and not unusual; everyday life; members of the public.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"The film shows the ordinary life of ordinary people in a small town."},{"number":70,"term":"last (v)","spoken":"last","ipa":"last /læst/","type":"verb","meaning":"kéo dài (bao lâu)","definition":"To continue for a particular period of time.","note":"","example":"The positive effect lasted for several hours after the session."},{"number":71,"term":"except (prep,conj) # besides (prep,adv)","spoken":"except , besides","ipa":"except /ɪˈksɛpt/ · besides /bɪˈsaɪdz/","type":"adverb · preposition · word family","meaning":"ngoại trừ # ngoài ra/ngoài…ra","definition":"Not including a person or thing.","note":"except + danh từ/đại từ; besides mang nghĩa “ngoài ra”.","example":"All the patients listened to music except one person in the control group."},{"number":72,"term":"lightning (n) · lightning strike","spoken":"lightning , lightning strike","ipa":"lightning /ˈlaɪtnɪŋ/ · strike /straɪk/","type":"noun · word family","meaning":"sét · cú sét đánh","definition":"A bright electrical flash in the sky; a lightning strike is an occasion when lightning hits something.","note":"lightning là ánh chớp/sét; thunder là tiếng sấm.","example":"A lightning strike damaged the equipment during the storm."},{"number":73,"term":"major (a) ~ main (a) · major (v) in st ~ specialize (v) in st","spoken":"major , main , major in something , specialize in something","ipa":"major /ˈmeɪdʒɚ/ · main /meɪn/ · specialize /ˈspɛʃəˌlaɪz/","type":"verb · adjective · phrase / pattern · word family","meaning":"chính/chủ yếu · học chuyên ngành nào ~ chuyên sâu về lĩnh vực nào","definition":"To focus professionally or academically on one subject; a major is the main university subject.","note":"specialize in dùng cho chuyên môn nghề nghiệp; major in dùng cho chuyên ngành học ở đại học.","example":"She specializes in international trade and majored in economics at university."},{"number":74,"term":"overall","spoken":"overall","ipa":"overall /ˈoʊvɚˌɔːl/","type":"word / phrase","meaning":"nhìn chung, tổng thể","definition":"Considering everything or the situation as a whole.","note":"","example":"Overall, the results suggest that music can improve attention."},{"number":75,"term":"whole (a) ~ entire (a) · as a whole · on the whole","spoken":"whole , entire , as a whole , on the whole","ipa":"whole /hoʊl/ · entire /ɪˈntaɪɚ/ · as /æz/","type":"adjective · phrase / pattern · word family","meaning":"toàn bộ · xét như một tổng thể · nhìn chung","definition":"Whole and entire mean complete; as a whole considers all parts together, while on the whole means generally.","note":"as a whole là xét toàn bộ; on the whole là nhìn chung.","example":"The whole group completed the task; on the whole, the results were positive."},{"number":76,"term":"condition (n)","spoken":"condition","ipa":"condition /kəˈndɪʃən/","type":"noun","meaning":"tình trạng, trạng thái","definition":"The state that a person, object, or situation is in.","note":"","example":"Doctors monitored the patient's condition throughout the music therapy session."},{"number":77,"term":"deal with ~ cope with ~ solve","spoken":"deal with , cope with , solve","ipa":"deal /diːl/ · cope /koʊp/ · solve /sɑːlv/","type":"phrasal verb · phrasal verb · verb · word family","meaning":"xử lí, ứng phó hoặc giải quyết","definition":"To take action in order to manage or solve a problem.","note":"deal with/cope with nhấn mạnh xử lí hoặc ứng phó; solve nhấn mạnh tìm ra lời giải.","example":"Music helped the patient cope with stress during treatment."},{"number":78,"term":"endure (v) · endurance (n)","spoken":"endure , endurance","ipa":"endure /ɛˈndjʊr/ · endurance /ˈɛndɚəns/","type":"verb · noun · word family","meaning":"chịu đựng · sức chịu đựng","definition":"To continue through pain or difficulty; endurance is the ability to do this.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Athletes use rhythm to endure demanding exercise and improve their endurance."},{"number":79,"term":"expert (n)","spoken":"expert","ipa":"expert /ˈɛkspɚt/","type":"noun","meaning":"chuyên gia","definition":"A person with specialist knowledge; specialist knowledge or skill.","note":"","example":"The expert shared her expertise through a short, clear lesson."},{"number":80,"term":"effect (n) · affect (v) · effective (a) · influence (n,v) · impact (n,v)","spoken":"effect , affect , effective , influence , impact","ipa":"effect /ɪˈfɛkt/ · affect /əˈfɛkt/ · effective /ɪˈfɛktɪv/ · influence /ˈɪnfluəns/ · impact /ˌɪˈmpækt/","type":"verb · noun · adjective · word family","meaning":"ảnh hưởng/kết quả · tác động đến · có hiệu quả · ảnh hưởng/tác động · tác động mạnh","definition":"A result or influence; to influence; producing the intended result.","note":"affect là động từ; effect là danh từ chỉ kết quả. influence thường là tác động dần dần; impact thường là tác động mạnh.","example":"The new method had an effect on the class and affected how students learned. Its impact and influence were strong because it was effective."},{"number":81,"term":"steady (a)","spoken":"steady","ipa":"steady /ˈstɛdi/","type":"adjective","meaning":"ổn định, đều đều, từ từ","definition":"Regular, stable, and not changing suddenly.","note":"","example":"A steady rhythm helped the patient walk at a regular pace."},{"number":82,"term":"study (v,n)","spoken":"study","ipa":"study /ˈstʌdi/","type":"verb · noun","meaning":"nghiên cứu","definition":"To examine a subject carefully in order to learn more about it.","note":"","example":"The researchers studied how background music affects memory during a learning task."},{"number":83,"term":"boost (v,n)","spoken":"boost","ipa":"boost /buːst/","type":"verb · noun","meaning":"tăng cường, thúc đẩy","definition":"To increase, improve, or strengthen something.","note":"","example":"A steady beat can boost confidence and give patients a sense of control."},{"number":84,"term":"treat (v)","spoken":"treat","ipa":"treat /triːt/","type":"verb","meaning":"điều trị bệnh","definition":"To give medical care to a person or deal with an illness.","note":"","example":"Doctors treated the illness with medicine and regular exercise."},{"number":85,"term":"concentrate (v) on ~ focus on · concentration (n)","spoken":"concentrate on , focus on , concentration","ipa":"concentrate /ˈkɑːnsəˌntreɪt/ · focus /ˈfoʊkəs/ · concentration /ˌkɑːnsəˈntreɪʃən/","type":"verb · noun · word family","meaning":"tập trung vào · sự tập trung","definition":"To give all your attention to something.","note":"concentrate on nhấn mạnh nỗ lực tinh thần; focus on nhấn mạnh hướng sự chú ý vào một điểm.","example":"Please concentrate on the text and focus on its main idea."},{"number":86,"term":"sharp (a)","spoken":"sharp","ipa":"sharp /ʃɑːrp/","type":"adjective","meaning":"sắc, sắc bén","definition":"Having a fine edge or point; also clear, sudden, or intense.","note":"","example":"The patient felt a sharp pain when she moved her arm."},{"number":87,"term":"in this way","spoken":"in this way","ipa":"this /ðɪs/ · way /weɪ/","type":"phrase / pattern","meaning":"bằng cách này…","definition":"By using the method or action that has just been described.","note":"","example":"In this way, music can support both movement and concentration."},{"number":88,"term":"activate (v)","spoken":"activate","ipa":"activate /ˈæktəˌveɪt/","type":"verb","meaning":"kích hoạt","definition":"To make a system, process, or device begin to work.","note":"","example":"Familiar music can activate areas of the brain linked to memory."},{"number":89,"term":"therefore ~ so","spoken":"therefore , so","ipa":"therefore /ˈðɛˌrfɔːr/ · so /soʊ/","type":"adverb · conjunction · word family","meaning":"vì vậy/do đó","definition":"For that reason; as a result.","note":"therefore trang trọng hơn so và thường nối hai ý theo quan hệ kết quả.","example":"The rhythm remained steady; therefore, the patient found it easier to walk."}],"pronunciationFocus":[{"entryNumber":50,"points":[{"category":"word-stress","note":"attract và distract đều nhấn trọng âm chính ở âm tiết cuối"},{"category":"final-sound","note":"Giữ đủ cụm /kt/ ở cuối attract và distract"}]},{"entryNumber":52,"points":[{"category":"word-stress","note":"attention /əˈtɛnʃən/: trọng âm chính ở âm tiết thứ hai"}]},{"entryNumber":55,"points":[{"category":"silent-letter","note":"psychology và psychologist: chữ p đầu từ không được phát âm"},{"category":"word-stress","note":"Cả hai từ đều nhấn trọng âm chính ở âm tiết /ˈkɑː/"}]},{"entryNumber":59,"points":[{"category":"final-sound","note":"depressed /dɪˈprɛst/: giữ rõ cụm /st/ ở cuối"}]},{"entryNumber":72,"points":[{"category":"silent-letter","note":"lightning /ˈlaɪtnɪŋ/: chữ gh không được phát âm"}]},{"entryNumber":85,"points":[{"category":"word-stress","note":"concentrate nhấn âm đầu; concentration chuyển trọng âm chính sang /ˈtreɪ/"}]}]}};
